        long lo = desc ? (long)b.V - (width - 1) : (long)b.V;
        long srcLo = lo < 0 ? 0 : lo;
        long srcHi = (lo + width) < a.W ? (lo + width) : a.W;
        if (srcLo >= srcHi) return Unknown(width);
        int count = (int)(srcHi - srcLo);
        int dstLo = (int)(srcLo - lo);
        int sLo = (int)srcLo;
